#include <iostream>
#include <bitset>
using namespace std;

bitset<550> grid[550];
bool used[550];
int cha[550];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        grid[a][b] = true;
        grid[b][a] = true;
    }

    for (int i = 1; i <= n; ++i)
        grid[i][i] = true;

    int tot = 0;
    int representative[4] = {};

    for (int i = 1; i <= n; ++i) {
        if (used[i])
            continue;

        used[i] = true;
        cha[i] = ++tot;

        if (tot < 4)
            representative[tot] = i;

        for (int j = i + 1; j <= n; ++j) {
            if (!used[j] && grid[i] == grid[j]) {
                used[j] = true;
                cha[j] = cha[i];
            }
        }
    }

    if (tot > 3) {
        cout << "NO\n";
        return 0;
    }

    char mapping[4] = {};

    if (tot == 1) {
        mapping[1] = 'a';
    } else if (tot == 2) {
        mapping[1] = 'a';
        mapping[2] = grid[representative[1]][representative[2]] ? 'b' : 'c';
    } else {
        int degree[4] = {};

        for (int i = 1; i <= 3; ++i) {
            for (int j = i + 1; j <= 3; ++j) {
                if (grid[representative[i]][representative[j]]) {
                    ++degree[i];
                    ++degree[j];
                }
            }
        }

        int center = 0;
        for (int i = 1; i <= 3; ++i) {
            if (degree[i] == 2) {
                if (center != 0) {
                    cout << "NO\n";
                    return 0;
                }
                center = i;
            } else if (degree[i] != 1) {
                cout << "NO\n";
                return 0;
            }
        }

        if (center == 0) {
            cout << "NO\n";
            return 0;
        }

        mapping[center] = 'b';
        char leaf = 'a';

        for (int i = 1; i <= 3; ++i) {
            if (i != center) {
                mapping[i] = leaf;
                leaf = 'c';
            }
        }
    }

    cout << "YES\n";
    for (int i = 1; i <= n; ++i)
        cout << mapping[cha[i]];
    cout << '\n';

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<bool>> graph(n, vector<bool>(n, false));
    vector<int> degree(n, 0);

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        if (!graph[a][b]) {
            graph[a][b] = graph[b][a] = true;
            ++degree[a];
            ++degree[b];
        }
    }

    string answer(n, 'b');
    int pivot = -1;

    for (int i = 0; i < n; ++i) {
        if (degree[i] != n - 1) {
            pivot = i;
            break;
        }
    }

    if (pivot != -1) {
        for (int i = 0; i < n; ++i) {
            if (degree[i] == n - 1) {
                answer[i] = 'b';
            } else if (i == pivot || graph[pivot][i]) {
                answer[i] = 'a';
            } else {
                answer[i] = 'c';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            bool shouldBeConnected = !(answer[i] == 'a' && answer[j] == 'c') &&
                                     !(answer[i] == 'c' && answer[j] == 'a');
            if (graph[i][j] != shouldBeConnected) {
                cout << "NO\n";
                return 0;
            }
        }
    }

    cout << "YES\n" << answer << '\n';
    return 0;
}

